#!/usr/bin/env node
/**
 * Emits the utility classes described by `utilities.spec.mjs`.
 *
 * Run with `--check` to verify the checked-in output matches a fresh run
 * without writing anything; that is what CI uses, so the generated file can
 * never drift from the spec that describes it.
 */
import { readFileSync, writeFileSync } from "node:fs";
import { dirname, join } from "node:path";
import { fileURLToPath } from "node:url";
import {
  BREAKPOINTS,
  OFFSET_SIDES,
  OFFSET_TOKENS,
  POSITION_VALUES,
  SPACING_EXTRAS,
  SPACING_FAMILIES,
  SPACING_TOKENS,
  offsetValue,
  spacingVar,
} from "./utilities.spec.mjs";

const ROOT = join(dirname(fileURLToPath(import.meta.url)), "..");

const BANNER = `/* GENERATED by scripts/generate-utilities.mjs — do not edit.
 * The class matrix lives in scripts/utilities.spec.mjs; change it there and
 * re-run \`pnpm generate:utilities\`. */\n`;

const rule = (selector, decls) =>
  `${selector} {\n${decls.map((d) => `  ${d}\n`).join("")}}\n`;

function spacing() {
  const out = [];
  for (const { prefix, props } of SPACING_FAMILIES) {
    out.push(`/* ${props.join(", ")} */`);
    for (const token of SPACING_TOKENS) {
      out.push(rule(`.${prefix}-${token}`, props.map((p) => `${p}: ${spacingVar(token)};`)));
    }
    out.push("");
  }
  for (const { selector, decls } of SPACING_EXTRAS) {
    out.push(rule(selector, decls));
  }
  return out.join("\n");
}

/**
 * Every rule a breakpoint repeats, as `[selectorSuffix, declarations]`. The
 * base pass emits them unprefixed; each breakpoint pass emits the same list
 * prefixed and wrapped in its media query. Writing the matrix once is the
 * whole point — position.scss was 1,548 lines because it wrote it five times.
 */
function positionRules() {
  const rules = [];
  for (const value of POSITION_VALUES) {
    rules.push([`position-${value}`, [`position: ${value};`]]);
  }
  for (const side of OFFSET_SIDES) {
    for (const token of OFFSET_TOKENS) {
      rules.push([`${side}-${token}`, [`${side}: ${offsetValue(token)};`]]);
    }
  }
  return rules;
}

function position() {
  const rules = positionRules();
  const out = [rules.map(([sel, decls]) => rule(`.${sel}`, decls)).join("\n")];

  for (const { key, maxWidth } of BREAKPOINTS) {
    const body = rules
      .map(([sel, decls]) => rule(`.${key}-${sel}`, decls))
      .join("\n")
      .replace(/^/gm, "  ")
      .replace(/^\s+$/gm, "");
    out.push(`@media (max-width: ${maxWidth}) {\n${body}}\n`);
  }
  return out.join("\n");
}

const TARGETS = [
  { file: "scss/styles/spacing.generated.scss", build: spacing },
  { file: "scss/styles/position.generated.scss", build: position },
];

const check = process.argv.includes("--check");
let drift = false;

for (const { file, build } of TARGETS) {
  const path = join(ROOT, file);
  const next = BANNER + "\n" + build();
  const current = (() => {
    try {
      return readFileSync(path, "utf8");
    } catch {
      return null;
    }
  })();

  if (check) {
    if (current !== next) {
      drift = true;
      console.error(`drift: ${file} does not match the spec — run \`pnpm generate:utilities\``);
    }
    continue;
  }

  if (current === next) {
    console.log(`unchanged  ${file}`);
    continue;
  }
  writeFileSync(path, next);
  const classes = (next.match(/^\./gm) || []).length;
  console.log(`written    ${file} (${classes} classes)`);
}

if (check && drift) process.exit(1);
if (check) console.log("generated utilities are up to date");
